  1→import { useCallback, useRef, useState, type DragEvent } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import { useConfig } from '../hooks/useConfig';
  4→import './FileUpload.css';
  5→
  6→const SUPPORTED_EXTENSIONS = ['.csv', '.json', '.parquet', '.xlsx'];
  7→
  8→interface FileUploadProps {
  9→  onUpload: (files: File[]) => Promise<void>;
 10→  onLoadSample: () => Promise<void>;
 11→}
 12→
 13→export function FileUpload({ onUpload, onLoadSample }: FileUploadProps) {
 14→  const { t } = useTranslation();
 15→  const { maxTotalSizeBytes } = useConfig();
 16→  const [dragging, setDragging] = useState(false);
 17→  const [uploading, setUploading] = useState(false);
 18→  const [loadingSample, setLoadingSample] = useState(false);
 19→  const inputRef = useRef<HTMLInputElement>(null);
 20→
 21→  const handleFiles = useCallback(async (fileList: FileList) => {
 22→    const files = Array.from(fileList);
 23→    const unsupported = files.filter(f => {
 24→      const ext = f.name.toLowerCase().slice(f.name.lastIndexOf('.'));
 25→      return !SUPPORTED_EXTENSIONS.includes(ext);
 26→    });
 27→    if (unsupported.length > 0) {
 28→      alert(t('unsupportedFormat'));
 29→      return;
 30→    }
 31→    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 32→    if (totalSize > maxTotalSizeBytes) {
 33→      alert(t('fileTooLarge', { maxSize: `${maxTotalSizeBytes / (1024 * 1024)}MB` }));
 34→      return;
 35→    }
 36→    setUploading(true);
 37→    try {
 38→      await onUpload(files);
 39→    } finally {
 40→      setUploading(false);
 41→    }
 42→  }, [onUpload, t, maxTotalSizeBytes]);
 43→
 44→  const handleLoadSample = useCallback(async () => {
 45→    setLoadingSample(true);
 46→    try {
 47→      await onLoadSample();
 48→    } finally {
 49→      setLoadingSample(false);
 50→    }
 51→  }, [onLoadSample]);
 52→
 53→  const onDrop = useCallback((e: DragEvent) => {
 54→    e.preventDefault();
 55→    setDragging(false);
 56→    if (e.dataTransfer.files.length > 0) handleFiles(e.dataTransfer.files);
 57→  }, [handleFiles]);
 58→
 59→  const onDragOver = useCallback((e: DragEvent) => {
 60→    e.preventDefault();
 61→    setDragging(true);
 62→  }, []);
 63→
 64→  const onDragLeave = useCallback(() => {
 65→    setDragging(false);
 66→  }, []);
 67→
 68→  return (
 69→    <div className="file-upload-wrapper">
 70→      <div
 71→        className={`file-upload ${dragging ? 'file-upload--dragging' : ''}`}
 72→        onDrop={onDrop}
 73→        onDragOver={onDragOver}
 74→        onDragLeave={onDragLeave}
 75→        onClick={() => inputRef.current?.click()}
 76→      >
 77→        <input
 78→          ref={inputRef}
 79→          type="file"
 80→          accept=".csv,.json,.parquet,.xlsx"
 81→          multiple
 82→          className="file-upload__input"
 83→          onChange={(e) => {
 84→            if (e.target.files && e.target.files.length > 0) handleFiles(e.target.files);
 85→            e.target.value = '';
 86→          }}
 87→        />
 88→        {uploading ? (
 89→          <p className="file-upload__text">{t('uploading')}</p>
 90→        ) : (
 91→          <p className="file-upload__text">
 92→            {t('uploadDropText', { maxSize: `${maxTotalSizeBytes / (1024 * 1024)}MB` })}
 93→          </p>
 94→        )}
 95→      </div>
 96→      <div className="file-upload-divider">
 97→        <span>{t('uploadOr')}</span>
 98→      </div>
 99→      <button
100→        className="file-upload-sample-btn"
101→        onClick={handleLoadSample}
102→        disabled={loadingSample}
103→      >
104→        {loadingSample ? t('loading') : t('loadSample')}
105→      </button>
106→    </div>
107→  );
108→}
