106→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
107→  const { t } = useTranslation();
108→  const { isStreaming, editMessage, deleteMessage } = useAgent();
109→  const [isEditing, setIsEditing] = useState(false);
110→  const [editText, setEditText] = useState(message.content);
111→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
112→  const textareaRef = useRef<HTMLTextAreaElement>(null);
113→
114→  const isUser = message.role === 'user';
115→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
116→
117→  useEffect(() => {
118→    if (isEditing && textareaRef.current) {
119→      textareaRef.current.focus();
120→      textareaRef.current.selectionStart = textareaRef.current.value.length;
121→    }
122→  }, [isEditing]);
123→
124→  const handleEdit = () => {
125→    setEditText(message.content);
126→    setIsEditing(true);
127→    setIsConfirmingDelete(false);
128→  };
129→
130→  const handleCancelEdit = () => {
131→    setIsEditing(false);
132→    setEditText(message.content);
133→  };
134→
135→  const handleSaveEdit = () => {
136→    const trimmed = editText.trim();
137→    if (!trimmed || trimmed === message.content) {
138→      handleCancelEdit();
139→      return;
140→    }
141→    setIsEditing(false);
142→    editMessage(messageIndex, trimmed);
143→  };
144→
145→  const handleDeleteConfirm = () => {
146→    setIsConfirmingDelete(false);
147→    deleteMessage(messageIndex);
148→  };
149→
150→  const handleKeyDown = (e: React.KeyboardEvent) => {
151→    if (e.key === 'Escape') {
152→      handleCancelEdit();
153→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
154→      e.preventDefault();
155→      handleSaveEdit();
156→    }
157→  };
158→
159→  let streamingRemainder: string | undefined;
160→  if (hasSegments && message.isStreaming && message.content) {
161→    const segmentedText = message.segments!
162→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
163→      .map((s) => s.text || '')
164→      .join('');
165→    const remaining = message.content.slice(segmentedText.length);
166→    if (remaining.trim()) {
167→      streamingRemainder = remaining;
168→    }
169→  }
170→
171→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
172→  const isInAnswerPhase = message.currentPhase === 'answer';
173→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
174→
175→  const hasCharts = hasSegments && message.segments!.some(
176→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
177→  );
178→
179→  const answerSegments = hasSegments
180→    ? message.segments!
181→        .filter((s) =>
182→          (s.type === 'answer' && s.text?.trim()) ||
183→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim())
184→        )
185→        .map((s) => hasCharts ? { ...s, text: stripChartSpecBlocks(s.text!) } : s)
186→        .filter((s) => s.text?.trim())
187→    : [];
188→
189→  const chartSegments = hasSegments
190→    ? message.segments!.filter(
191→        (s) =>
192→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
193→          (s.type === 'subagent_end' && s.chart_spec)
194→      )
195→    : [];
196→
197→  const questionSegments = hasSegments
198→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
199→    : [];
200→
201→  return (
202→    <div className={`message-bubble message-bubble--${message.role}`}>
203→      <div className="message-bubble__header">
204→        {isUser ? t('you') : t('assistant')}
205→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
206→          <span className="message-bubble__actions">
207→            <button
208→              className="message-bubble__action-btn"
209→              onClick={handleEdit}
210→              title={t('editMessage')}
211→            >
212→              &#9998;
213→            </button>
214→            <button
215→              className="message-bubble__action-btn message-bubble__action-btn--delete"
216→              onClick={() => setIsConfirmingDelete(true)}
217→              title={t('deleteMessage')}
218→            >
219→              &#128465;
220→            </button>
221→          </span>
222→        )}
223→      </div>
224→
225→      {isUser && isConfirmingDelete && (
226→        <div className="message-bubble__confirm-delete">
227→          <span>{t('deleteConfirm')}</span>
228→          <div className="message-bubble__confirm-actions">
229→            <button
230→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
231→              onClick={handleDeleteConfirm}
232→            >
233→              {t('delete')}
234→            </button>
235→            <button
236→              className="message-bubble__confirm-btn"
237→              onClick={() => setIsConfirmingDelete(false)}
238→            >
239→              {t('cancel')}
240→            </button>
241→          </div>
242→        </div>
243→      )}
244→
245→      {isUser && isEditing ? (
246→        <div className="message-bubble__edit-mode">
247→          <textarea
248→            ref={textareaRef}
249→            className="message-bubble__edit-textarea"
250→            value={editText}
251→            onChange={(e) => setEditText(e.target.value)}
252→            onKeyDown={handleKeyDown}
253→            rows={3}
254→          />
255→          <div className="message-bubble__edit-actions">
256→            <button
257→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
258→              onClick={handleSaveEdit}
259→            >
260→              {t('saveResend')}
261→            </button>
262→            <button
263→              className="message-bubble__edit-btn"
264→              onClick={handleCancelEdit}
265→            >
266→              {t('cancel')}
267→            </button>
268→          </div>
269→        </div>
270→      ) : hasSegments ? (
271→        <div className="message-bubble__segments">
272→          {!questionSegments.some((s) => !s.userAnswer) && (
273→            <ThinkingBlock
274→              segments={message.segments!}
275→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
276→              isThinkingPhase={isThinkingPhase}
277→              isAgentStreaming={!!message.isStreaming}
278→            />
279→          )}
280→          {questionSegments.map((seg, i) => (
281→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
282→              <UserQuestion
283→                questionData={seg.questionData!}
284→                userAnswer={seg.userAnswer}
285→                userFreeText={seg.userFreeText}
286→              />
287→            </div>
288→          ))}
289→          {(chartSegments.length > 0 || answerSegments.length > 0) && (
290→            <div className="message-bubble__segment message-bubble__segment--answer">
291→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
292→              {chartSegments.map((seg, i) => (
293→                <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
294→                  {seg.type === 'tool' && seg.toolResult ? (
295→                    <InlineQueryResult result={seg.toolResult!} />
296→                  ) : seg.chart_spec ? (
297→                    <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
298→                  ) : null}
299→                </div>
300→              ))}
301→              {answerSegments.map((seg, i) => (
302→                <div key={`answer-${i}`} className="message-bubble__segment-content">
303→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
304→                </div>
305→              ))}
306→            </div>
307→          )}
308→          {isInAnswerPhase && streamingRemainder?.trim() && (() => {
309→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
310→            return displayText?.trim() ? (
311→              <div className="message-bubble__segment message-bubble__segment--answer">
312→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
313→                <div className="message-bubble__segment-content">
314→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
315→                </div>
316→              </div>
317→            ) : null;
318→          })()}
319→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
320→            <span className="message-bubble__typing">{t('thinking')}</span>
321→          )}
322→        </div>
323→      ) : (
324→        <>
325→          <div className="message-bubble__content">
326→            {message.content ? (
327→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
328→            ) : message.isStreaming ? (
329→              <span className="message-bubble__typing">{t('thinking')}</span>
330→            ) : null}
331→          </div>
332→          {message.toolCalls && message.toolCalls.length > 0 && (
333→            <div className="message-bubble__tools">
334→              {message.toolCalls.map((tc) => (
335→                <InlineQueryResult key={tc.toolCallId} result={tc} />
336→              ))}
337→            </div>
338→          )}
339→        </>
340→      )}
341→    </div>
342→  );
343→}
