 1→import Plot from 'react-plotly.js';
 2→
 3→interface ChartWidgetProps {
 4→  data: unknown[];
 5→  layout?: Record<string, unknown>;
 6→  frames?: unknown[];
 7→}
 8→
 9→export function ChartWidget({ data, layout, frames }: ChartWidgetProps) {
10→  // Normalize layout.title: Plotly v3 requires {text: "..."} object form
11→  const normalizedLayout = { ...layout };
12→  if (typeof normalizedLayout.title === 'string') {
13→    normalizedLayout.title = { text: normalizedLayout.title };
14→  }
15→
16→  // frames can live at the top level or inside layout (common variant);
17→  // extract from layout so Plotly receives them as a dedicated prop.
18→  const resolvedFrames = frames || (normalizedLayout.frames as unknown[]);
19→  delete normalizedLayout.frames;
20→
21→  return (
22→    <Plot
23→      data={data as Plotly.Data[]}
24→      layout={{ autosize: true, height: 400, ...normalizedLayout } as Partial<Plotly.Layout>}
25→      frames={resolvedFrames as Plotly.Frame[] | undefined}
26→      useResizeHandler
27→      style={{ width: '100%' }}
28→      config={{ responsive: true, displayModeBar: true }}
29→    />
30→  );
31→}
