  1→import { useState, useMemo, useRef, useEffect } from 'react';
  2→import { useTranslation } from '../hooks/useTranslation';
  3→import type { QueryResult } from '../types';
  4→import './ResultsTable.css';
  5→
  6→interface ResultsTableProps {
  7→  result: QueryResult | null;
  8→}
  9→
 10→const DISPLAY_CAP = 1000;
 11→
 12→interface SortConfig {
 13→  column: string | null;
 14→  direction: 'asc' | 'desc';
 15→}
 16→
 17→export function ResultsTable({ result }: ResultsTableProps) {
 18→  const { t } = useTranslation();
 19→  const [sortConfig, setSortConfig] = useState<SortConfig>({ column: null, direction: 'asc' });
 20→  const [columnFilters, setColumnFilters] = useState<Record<string, string>>({});
 21→  const [globalFilter, setGlobalFilter] = useState('');
 22→  const prevResult = useRef<QueryResult | null>(null);
 23→
 24→  useEffect(() => {
 25→    if (result !== prevResult.current) {
 26→      prevResult.current = result;
 27→      setSortConfig({ column: null, direction: 'asc' });
 28→      setColumnFilters({});
 29→      setGlobalFilter('');
 30→    }
 31→  }, [result]);
 32→
 33→  const filteredRows = useMemo(() => {
 34→    if (!result) return [];
 35→    let rows = result.rows;
 36→
 37→    if (globalFilter) {
 38→      const term = globalFilter.toLowerCase();
 39→      rows = rows.filter((row) =>
 40→        result.columns.some((col) => formatCell(row[col]).toLowerCase().includes(term))
 41→      );
 42→    }
 43→
 44→    const activeFilters = Object.entries(columnFilters).filter(([, v]) => v);
 45→    if (activeFilters.length > 0) {
 46→      rows = rows.filter((row) =>
 47→        activeFilters.every(([col, term]) =>
 48→          formatCell(row[col]).toLowerCase().includes(term.toLowerCase())
 49→        )
 50→      );
 51→    }
 52→
 53→    return rows;
 54→  }, [result, globalFilter, columnFilters]);
 55→
 56→  const sortedRows = useMemo(() => {
 57→    if (!sortConfig.column) return filteredRows;
 58→    const col = sortConfig.column;
 59→    const dir = sortConfig.direction === 'asc' ? 1 : -1;
 60→
 61→    return [...filteredRows].sort((a, b) => {
 62→      const aVal = a[col];
 63→      const bVal = b[col];
 64→
 65→      if (aVal === null || aVal === undefined) return 1;
 66→      if (bVal === null || bVal === undefined) return -1;
 67→
 68→      const aNum = Number(aVal);
 69→      const bNum = Number(bVal);
 70→      if (!isNaN(aNum) && !isNaN(bNum)) return (aNum - bNum) * dir;
 71→
 72→      return String(aVal).localeCompare(String(bVal)) * dir;
 73→    });
 74→  }, [filteredRows, sortConfig]);
 75→
 76→  if (!result) return null;
 77→
 78→  const isFiltered = globalFilter || Object.values(columnFilters).some(Boolean);
 79→  const displayRows = sortedRows.slice(0, DISPLAY_CAP);
 80→  const truncated = sortedRows.length > DISPLAY_CAP;
 81→
 82→  function handleSort(col: string) {
 83→    setSortConfig((prev) => {
 84→      if (prev.column !== col) return { column: col, direction: 'asc' };
 85→      if (prev.direction === 'asc') return { column: col, direction: 'desc' };
 86→      return { column: null, direction: 'asc' };
 87→    });
 88→  }
 89→
 90→  function handleColumnFilter(col: string, value: string) {
 91→    setColumnFilters((prev) => ({ ...prev, [col]: value }));
 92→  }
 93→
 94→  function getSortIcon(col: string) {
 95→    if (sortConfig.column !== col) return ' ↕';
 96→    return sortConfig.direction === 'asc' ? ' ↑' : ' ↓';
 97→  }
 98→
 99→  return (
100→    <div className="results-table">
101→      <div className="results-table__toolbar">
102→        <input
103→          className="results-table__global-search"
104→          type="text"
105→          placeholder={t('searchColumns')}
106→          value={globalFilter}
107→          onChange={(e) => setGlobalFilter(e.target.value)}
108→        />
109→      </div>
110→      <div className="results-table__summary">
111→        {isFiltered
112→          ? t('rowsFilteredInTime', { count: sortedRows.length, total: result.rowCount, time: result.executionTimeMs.toFixed(1) })
113→          : t('rowCountInTime', { count: result.rowCount, time: result.executionTimeMs.toFixed(1) })}
114→        {truncated && ` ${t('showingFirst', { count: DISPLAY_CAP })}`}
115→      </div>
116→      {result.columns.length > 0 && (
117→        <div className="results-table__scroll">
118→          <table className="results-table__table">
119→            <thead>
120→              <tr>
121→                {result.columns.map((col) => (
122→                  <th key={col}>
123→                    <button
124→                      className="results-table__col-header"
125→                      onClick={() => handleSort(col)}
126→                    >
127→                      {col}
128→                      <span
129→                        className={`results-table__sort-icon${sortConfig.column === col ? ' results-table__sort-icon--active' : ''}`}
130→                      >
131→                        {getSortIcon(col)}
132→                      </span>
133→                    </button>
134→                    <input
135→                      className="results-table__col-filter"
136→                      type="text"
137→                      placeholder={t('filterPlaceholder')}
138→                      value={columnFilters[col] || ''}
139→                      onChange={(e) => handleColumnFilter(col, e.target.value)}
140→                    />
141→                  </th>
142→                ))}
143→              </tr>
144→            </thead>
145→            <tbody>
146→              {displayRows.map((row, i) => (
147→                <tr key={i}>
148→                  {result.columns.map((col) => (
149→                    <td key={col}>{formatCell(row[col])}</td>
150→                  ))}
151→                </tr>
152→              ))}
153→            </tbody>
154→          </table>
155→        </div>
156→      )}
157→    </div>
158→  );
159→}
160→
161→function formatCell(value: unknown): string {
162→  if (value === null || value === undefined) return 'NULL';
163→  if (typeof value === 'object') return JSON.stringify(value);
164→  return String(value);
165→}
